/// The value name of a flag: `name`, else its kind's, then its range: `INTEGER 1..100`.
pub(super) fn value_name(kind: Kind, name: &'static str, range: &str) -> String {
    let name = match (name, kind) {
        ("", Kind::String) => "STRING",
        ("", Kind::Integer) => "INTEGER",
        ("", Kind::Number) => "NUMBER",
        ("", Kind::Boolean) => "BOOL",
        ("", Kind::Json) => "JSON",
        (name, _) => name,
    };
    match range {
        "" => name.to_owned(),
        range => format!("{name} {range}"),
    }
}

/// `(required) help` for a required flag, `(deprecated) help` for a deprecated one.
pub(super) fn required_help(required: bool, deprecated: bool, help: &str) -> String {
    let marks = [(required, "(required)"), (deprecated, "(deprecated)")];
    let marks = marks.iter().filter(|(on, _)| *on).map(|(_, mark)| *mark);
    marks
        .chain(Some(help).filter(|help| !help.is_empty()))
        .collect::<Vec<_>>()
        .join(" ")
}

/// `arg` with `[default: <default>]` after its help, when the API has a default.
pub(super) fn noted(arg: Arg, default: &str) -> Arg {
    if default.is_empty() {
        return arg;
    }
    let help = arg.get_help().map(ToString::to_string).unwrap_or_default();
    arg.help(format!("{help} [default: {default}]").trim().to_owned())
}

/// Numbers and enum values may start with `-`; repeatable ones also take `a,b,c`, as
/// they cannot contain a comma (`<STRING,...>`), others say they repeat.
pub(super) fn lists(arg: Arg, kind: Kind, many: bool, values: &[&str]) -> Arg {
    let numeric = matches!(kind, Kind::Integer | Kind::Number);
    let arg = match numeric || values.iter().any(|value| value.starts_with('-')) {
        true => arg.allow_hyphen_values(true),
        false => arg,
    };
    let commas = values.iter().all(|value| !value.contains(','));
    let name = arg
        .get_value_names()
        .and_then(|names| names.first())
        .map(ToString::to_string)
        .unwrap_or_default();
    match (many, numeric || (!values.is_empty() && commas)) {
        (false, _) => arg,
        (true, true) => arg.value_delimiter(',').value_name(format!("{name},...")),
        (true, false) => {
            let help = arg.get_help().map(ToString::to_string).unwrap_or_default();
            arg.help(format!("{help} (repeatable)").trim().to_owned())
        }
    }
}

/// Values past this many are hidden from help, which shows a few.
const SHOWN_VALUES: usize = 12;

/// `arg` with `help` when there is one, accepting only `values` when there are some.
pub(super) fn described(arg: Arg, help: String, values: &'static [&'static str]) -> Arg {
    let arg = match help.as_str() {
        "" => arg,
        _ => arg.help(help.clone()),
    };
    if values.len() <= SHOWN_VALUES {
        return match values {
            [] => arg,
            values => arg.value_parser(values.to_vec()),
        };
    }
    let some = values[..3].join(", ");
    let help = match help.as_str() {
        "" => format!("One of {} values: {some}…", values.len()),
        help => format!("{help} [one of {} values: {some}…]", values.len()),
    };
    arg.value_parser(values.to_vec())
        .hide_possible_values(true)
        .help(help)
}

