/// A body assembled from the command line, not decoded yet.
#[derive(Clone, Debug)]
pub struct Body<'f> {
    value: Option<Value>,
    fields: &'f [Field],
}

impl<'f> Body<'f> {
    /// Reads `--data` and the field flags of `fields` from `matches`.
    pub fn from_matches(
        matches: &ArgMatches,
        fields: &'f [Field],
        stdin: &mut dyn Read,
    ) -> Result<Self, CliError> {
        let data = matches.get_one::<String>(DATA).map(String::as_str);
        let values = fields.iter().filter_map(|field| {
            let values = matches.get_many::<String>(field.flag)?;
            Some((field, values.map(String::as_str).collect::<Vec<_>>()))
        });
        Self::assemble(data, values, fields, stdin)
    }

    /// `data` as the base, then each field set to its values (several only for `many` fields).
    /// Shallower fields apply first, so `--address '{…}' --address.city X` merges.
    pub fn assemble<'v>(
        data: Option<&str>,
        values: impl IntoIterator<Item = (&'v Field, Vec<&'v str>)>,
        fields: &'f [Field],
        stdin: &mut dyn Read,
    ) -> Result<Self, CliError> {
        let mut value = data.map(|data| read_data(data, stdin)).transpose()?;
        let mut values: Vec<_> = values.into_iter().collect();
        values.sort_by_key(|(field, _)| field.parents.len());
        for (field, texts) in values {
            let json = if field.many {
                Value::Array(
                    texts
                        .iter()
                        .map(|text| coerce(field, text))
                        .collect::<Result<_, _>>()?,
                )
            } else {
                match texts.last() {
                    Some(text) => coerce(field, text)?,
                    None => continue,
                }
            };
            let root = value.get_or_insert_with(|| Value::Object(Map::new()));
            set(root, field, json)?;
        }
        Ok(Self { value, fields })
    }

    /// Whether neither `--data` nor any field flag was given.
    pub fn is_empty(&self) -> bool {
        self.value.is_none()
    }

    /// Checks the body against the schema of the command `key` (see `schema`), unless nothing
    /// was given for an optional body.
    pub fn validate(self, ctx: &Ctx, key: &str, optional: bool) -> Result<Self, CliError> {
        if optional && self.value.is_none() {
            return Ok(self);
        }
        let schema = Schema::parse(ctx.app.schema)?;
        let allow_unknown = ctx.globals.allow_unknown_fields;
        schema.check_body(key, &self.value(), self.fields, allow_unknown)?;
        Ok(self)
    }

    /// The body, `{}` when nothing was given.
    pub fn value(&self) -> Value {
        self.value
            .clone()
            .unwrap_or_else(|| Value::Object(Map::new()))
    }

    /// The request type of a required body; missing fields are reported with their flag.
    pub fn decode<T: DeserializeOwned>(self) -> Result<T, CliError> {
        let value = self.value.unwrap_or_else(|| Value::Object(Map::new()));
        decode(value, self.fields)
    }

    /// The request type of an optional body: `None` when nothing was given.
    pub fn decode_optional<T: DeserializeOwned>(self) -> Result<Option<T>, CliError> {
        match self.value {
            Some(value) => decode(value, self.fields).map(Some),
            None => Ok(None),
        }
    }
}

/// `serde_json::from_value`, with errors naming the property path and the flag setting it.
pub fn decode<T: DeserializeOwned>(value: Value, fields: &[Field]) -> Result<T, CliError> {
    serde_path_to_error::deserialize(value).map_err(|error| {
        let parent = error.path().to_string();
        let parent = if parent == "." { String::new() } else { parent };
        let inner = error.into_inner().to_string();
        let missing = inner
            .strip_prefix("missing field `")
            .and_then(|rest| rest.strip_suffix('`'));
        let (path, required) = match missing {
            Some(name) if parent.is_empty() => (name.to_owned(), true),
            Some(name) => (format!("{parent}.{name}"), true),
            None => (parent, false),
        };
        let flag = fields
            .iter()
            .find(|field| field.path() == path)
            .map(|field| format!(" (--{})", field.flag))
            .unwrap_or_default();
        CliError::usage(match (path.is_empty(), required) {
            (_, true) => format!("invalid body: `{path}`{flag} is required"),
            (true, false) => format!("invalid body: {inner}"),
            (false, false) => format!("invalid body at `{path}`{flag}: {inner}"),
        })
    })
}

fn read_data(data: &str, stdin: &mut dyn Read) -> Result<Value, CliError> {
    let (text, origin) = match data {
        "-" | "@-" => {
            let mut text = String::new();
            stdin
                .read_to_string(&mut text)
                .map_err(|error| CliError::usage(format!("--data: cannot read stdin: {error}")))?;
            (text, "stdin".to_owned())
        }
        _ => match data.strip_prefix('@') {
            Some(path) => {
                let text = fs::read_to_string(path).map_err(|error| {
                    CliError::usage(format!("--data: cannot read {path}: {error}"))
                })?;
                (text, path.to_owned())
            }
            None => return parse_json(data, "--data"),
        },
    };
    if text.trim().is_empty() {
        return Err(CliError::usage(format!("--data: {origin} is empty")));
    }
    parse_json(&text, &format!("--data ({origin})"))
}

fn parse_json(text: &str, what: &str) -> Result<Value, CliError> {
    serde_json::from_str(text)
        .map_err(|error| CliError::usage(format!("{what}: invalid JSON: {error}")))
}

fn coerce(field: &Field, text: &str) -> Result<Value, CliError> {
    let expected =
        |what: &str| CliError::usage(format!("--{}: expected {what}, got `{text}`", field.flag));
    match field.kind {
        Kind::String => Ok(Value::String(text.to_owned())),
        Kind::Integer => text
            .parse::<i64>()
            .map(Value::from)
            .or_else(|_| text.parse::<u64>().map(Value::from))
            .map_err(|_| expected("an integer")),
        Kind::Number => serde_json::from_str::<Number>(text.trim())
            .map(Value::Number)
            .map_err(|_| expected("a number")),
        Kind::Boolean => match text {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            _ => Err(expected("true or false")),
        },
        Kind::Json => serde_json::from_str(text)
            .map_err(|error| CliError::usage(format!("--{}: invalid JSON: {error}", field.flag))),
    }
}

fn set(root: &mut Value, field: &Field, json: Value) -> Result<(), CliError> {
    let mut node = root;
    let mut walked = Vec::new();
    for segment in field.parents.iter().copied() {
        node = object(node, field, &walked)?
            .entry(segment)
            .or_insert_with(|| Value::Object(Map::new()));
        walked.push(segment);
    }
    object(node, field, &walked)?.insert(field.key.to_owned(), json);
    Ok(())
}

fn object<'v>(
    node: &'v mut Value,
    field: &Field,
    walked: &[&str],
) -> Result<&'v mut Map<String, Value>, CliError> {
    let kind = match node {
        Value::Object(map) => return Ok(map),
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
    };
    let what = if walked.is_empty() {
        "the --data body".to_owned()
    } else {
        format!("`{}` in --data", walked.join("."))
    };
    Err(CliError::usage(format!(
        "--{}: {what} is {kind}, not an object",
        field.flag
    )))
}

#[cfg(test)]
mod tests {
    use std::io::{self, Write};

    use clap::Command;
    use serde::Deserialize;
    use serde_json::json;

    use super::*;

    const FIELDS: &[Field] = &[
        Field::new("name", "name", Kind::String).help("The thing's name"),
        Field::new("quantity", "quantity", Kind::Integer),
        Field::new("price", "price", Kind::Number),
        Field::new("active", "active", Kind::Boolean),
        Field::new("metadata", "metadata", Kind::Json),
        Field::new("tag", "tags", Kind::String).many(),
        Field::new("address", "address", Kind::Json),
        Field::new("address.city", "city", Kind::String).under(&["address"]),
        Field::new("limits.max", "max", Kind::Integer).under(&["limits"]),
        Field::new("a.b", "a.b", Kind::String),
    ];

    fn command() -> Command {
        Command::new("create").args(args(FIELDS))
    }

    fn body(argv: &[&str], stdin: &str) -> Result<Value, CliError> {
        let matches =
            command().try_get_matches_from(std::iter::once("create").chain(argv.iter().copied()));
        let matches = matches.map_err(|e| CliError::usage(e.to_string()))?;
        Body::from_matches(&matches, FIELDS, &mut stdin.as_bytes()).map(|body| body.value())
    }

    fn error(argv: &[&str]) -> String {
        body(argv, "").unwrap_err().message().to_owned()
    }

    #[test]
    fn nothing_given_is_an_empty_body() {
        let matches = command().get_matches_from(["create"]);
        let body = Body::from_matches(&matches, FIELDS, &mut io::empty()).unwrap();
        assert!(body.is_empty());
        assert_eq!(body.value(), json!({}));
        assert_eq!(body.decode_optional::<Value>().unwrap(), None);
    }

    #[test]
    fn flags_are_coerced_to_their_kind() {
        let value = body(
            &[
                "--name",
                "Widget",
                "--quantity",
                "3",
                "--price",
                "9.5",
                "--active",
                "--metadata",
                r#"{"a": [1]}"#,
            ],
            "",
        )
        .unwrap();
        assert_eq!(
            value,
            json!({"name": "Widget", "quantity": 3, "price": 9.5, "active": true, "metadata": {"a": [1]}})
        );
        assert_eq!(
            body(&["--active=false"], "").unwrap(),
            json!({"active": false})
        );
        assert_eq!(body(&["--price", "10"], "").unwrap(), json!({"price": 10}));
    }

    #[test]
    fn repeated_flags_build_arrays() {
        assert_eq!(
            body(&["--tag", "a", "--tag", "b"], "").unwrap(),
            json!({"tags": ["a", "b"]})
        );
    }

    #[test]
    fn dotted_paths_create_nested_objects() {
        assert_eq!(
            body(&["--address.city", "Paris", "--limits.max", "5"], "").unwrap(),
            json!({"address": {"city": "Paris"}, "limits": {"max": 5}})
        );
    }

    #[test]
    fn dotted_keys_of_the_body_stay_one_key() {
        assert_eq!(body(&["--a.b", "x"], "").unwrap(), json!({"a.b": "x"}));
    }

    #[test]
    fn flags_override_data_and_merge_into_its_objects() {
        let value = body(
            &[
                "--data",
                r#"{"name": "Old", "address": {"city": "Lyon", "zip": "69000"}, "tags": ["x"]}"#,
                "--name",
                "New",
                "--address.city",
                "Paris",
                "--tag",
                "y",
            ],
            "",
        )
        .unwrap();
        assert_eq!(
            value,
            json!({"name": "New", "address": {"city": "Paris", "zip": "69000"}, "tags": ["y"]})
        );
        let merged = body(
            &[
                "--address.city",
                "Paris",
                "--address",
                r#"{"zip": "75001"}"#,
            ],
            "",
        )
        .unwrap();
        assert_eq!(
            merged,
            json!({"address": {"zip": "75001", "city": "Paris"}})
        );
    }

    #[test]
    fn data_reads_files_and_stdin() {
        let mut file = tempfile::NamedTempFile::new().unwrap();
        write!(file, r#"{{"name": "From file", "quantity": 1}}"#).unwrap();
        let at_file = format!("@{}", file.path().display());
        assert_eq!(
            body(&["--data", &at_file, "--quantity", "2"], "").unwrap(),
            json!({"name": "From file", "quantity": 2})
        );
        assert_eq!(
            body(&["-d", "-"], r#"{"name": "piped"}"#).unwrap(),
            json!({"name": "piped"})
        );
        assert_eq!(body(&["-d", "@-"], r#"[1, 2]"#).unwrap(), json!([1, 2]));
    }

    #[test]
    fn data_errors_say_where_the_json_came_from() {
        assert!(error(&["-d", "{"]).starts_with("--data: invalid JSON: EOF while parsing"));
        assert_eq!(
            body(&["-d", "-"], "  \n").unwrap_err().message(),
            "--data: stdin is empty"
        );
        assert!(error(&["-d", "@/nonexistent/body.json"])
            .starts_with("--data: cannot read /nonexistent/body.json: "));
        let bad = body(&["-d", "-"], "{\"a\": }").unwrap_err();
        assert!(
            bad.message().starts_with("--data (stdin): invalid JSON: "),
            "{bad}"
        );
        assert_eq!(bad.exit_code(), super::super::error::exit::USAGE);
    }

    #[test]
    fn coercion_errors_name_the_flag() {
        assert_eq!(
            error(&["--quantity", "3.5"]),
            "--quantity: expected an integer, got `3.5`"
        );
        assert_eq!(
            error(&["--price", "abc"]),
            "--price: expected a number, got `abc`"
        );
        assert!(error(&["--metadata", "{a}"]).starts_with("--metadata: invalid JSON: "));
        let boolean = Body::assemble(
            Some("{}"),
            [(&FIELDS[3], vec!["yes"])],
            FIELDS,
            &mut io::empty(),
        )
        .unwrap_err();
        assert_eq!(
            boolean.message(),
            "--active: expected true or false, got `yes`"
        );
    }

    #[test]
    fn fields_cannot_go_through_non_objects() {
        assert_eq!(
            error(&["-d", r#"{"address": "Paris"}"#, "--address.city", "Lyon"]),
            "--address.city: `address` in --data is a string, not an object"
        );
        assert_eq!(
            error(&["-d", "[1]", "--name", "x"]),
            "--name: the --data body is an array, not an object"
        );
    }

    #[derive(Debug, Deserialize, PartialEq)]
    struct Address {
        city: String,
    }

    #[derive(Debug, Deserialize, PartialEq)]
    struct CreateThing {
        name: String,
        quantity: Option<i64>,
        address: Option<Address>,
    }

    fn decoded(argv: &[&str]) -> Result<CreateThing, CliError> {
        let matches =
            command().get_matches_from(std::iter::once("create").chain(argv.iter().copied()));
        Body::from_matches(&matches, FIELDS, &mut io::empty())?.decode()
    }

    #[test]
    fn decoding_gives_the_typed_request() {
        assert_eq!(
            decoded(&["--name", "Widget", "--address.city", "Paris"]).unwrap(),
            CreateThing {
                name: "Widget".into(),
                quantity: None,
                address: Some(Address {
                    city: "Paris".into()
                }),
            }
        );
    }

    #[test]
    fn decoding_errors_name_the_path_and_the_flag() {
        assert_eq!(
            decoded(&[]).unwrap_err().message(),
            "invalid body: `name` (--name) is required"
        );
        assert_eq!(
            decoded(&["--name", "x", "--address", "{}"])
                .unwrap_err()
                .message(),
            "invalid body: `address.city` (--address.city) is required"
        );
        let wrong = decoded(&["-d", r#"{"name": 3}"#]).unwrap_err();
        assert_eq!(
            wrong.message(),
            "invalid body at `name` (--name): invalid type: integer `3`, expected a string"
        );
        assert_eq!(wrong.exit_code(), super::super::error::exit::USAGE);
        let no_flag =
            decode::<CreateThing>(json!({"name": "x", "quantity": "many"}), &[]).unwrap_err();
        assert_eq!(
            no_flag.message(),
            "invalid body at `quantity`: invalid type: string \"many\", expected i64"
        );
        let not_object = decode::<CreateThing>(json!("x"), FIELDS).unwrap_err();
        assert_eq!(
            not_object.message(),
            "invalid body: invalid type: string \"x\", expected struct CreateThing"
        );
    }

    #[test]
    fn boolean_flags_take_no_separate_value() {
        let matches = command()
            .try_get_matches_from(["create", "--active", "--name", "x"])
            .unwrap();
        assert_eq!(
            matches.get_one::<String>("active").map(String::as_str),
            Some("true")
        );
        assert!(command()
            .try_get_matches_from(["create", "--active=maybe"])
            .is_err());
    }
}
